script:
HIGH = 'High'

if doc.get('custom_risk_rating') == HIGH and not doc.get('custom_risk_review_date'):
    frappe.throw('Risk Review Date is required when Vendor Risk Rating is High.')

MIN_YEARS = 2
MIN_MONTHS = 3

state = doc.get('workflow_state') or ''
if state in ('Under Review', 'Approved'):
    est = doc.get('custom_establishment_date')
    if not est:
        frappe.throw('Establishment Date is required before review/approval.')
    today = frappe.utils.getdate(frappe.utils.today())
    years = (today - frappe.utils.getdate(est)).days / 365.0
    if years < MIN_YEARS:
        frappe.throw('Supplier must be in existence for at least {0} years.'.format(MIN_YEARS))

    months = frappe.utils.cint(doc.get('custom_product_availability_months') or 0)
    if months < MIN_MONTHS:
        frappe.throw('Product must be available in the civil market for at least {0} months.'.format(MIN_MONTHS))

    if doc.get('custom_is_sole_marketer') != 'Yes':
        frappe.throw('Supplier must be the sole marketer (set Is Sole Marketer to "Yes").')

REQUIRED = ("Turnover and sales certificate", "Factory location")
if doc.get('custom_document_type') in REQUIRED:
    if not doc.get('custom_file'):
        frappe.throw('Attachment required for ' + (doc.get('custom_document_type') or 'this document'))

# validation will block save if missing attachment.

REQUIRED = ("Turnover and sales certificate", "Factory location")
found = []
docs = doc.get('custom_supporting_documents') or []
for d in docs:
    dt = d.get('custom_document_type')
    f = d.get('custom_file')
    if dt in REQUIRED and f:
        if dt not in found:
            found.append(dt)
missing = []
for r in REQUIRED:
    if r not in found:
        missing.append(r)
if missing:
    frappe.throw('Please upload required supporting documents before saving: ' + ', '.join(missing))
else:
    # mark eligibility complete when the required supporting docs are present
    doc.custom_eligibility_complete = 1

MIN_TAX_ID_LEN = 6
MIN_BANK_ACCT_NO_LEN = 6
MIN_IBAN_LEN = 15
MAX_IBAN_LEN = 34

# Basic email check
email = doc.get('email_id')
if email:
    ok = frappe.utils.validate_email_address(email, False)
    if not ok:
        frappe.throw('Email ID is not valid.')

# Basic website URL check
website = doc.get('website')
if website:
    ok = frappe.utils.validate_url(website, False)
    if not ok:
        frappe.throw('Website URL is not valid.')

# Basic phone check (primary mobile if available)
mobile = doc.get('mobile_no')
if mobile:
    ok = frappe.utils.validate_phone_number(mobile, False)
    if not ok:
        frappe.throw('Mobile number is not valid.')

# Basic UPI check (very light since no regex allowed)
upi = doc.get('custom_upi_id')
if upi:
    if ' ' in upi or '@' not in upi or len(upi) < 5:
        frappe.throw('UPI ID seems invalid. It should contain "@" and no spaces.')

# Tax ID presence/format (if provided)
tax_id = doc.get('tax_id')
if tax_id:
    if len(tax_id) < MIN_TAX_ID_LEN or not tax_id.replace(' ', '').isalnum():
        frappe.throw('Tax ID format looks invalid (min length and alphanumeric expected).')

# Default Bank Account validations (if linked)
def_bank = doc.get('default_bank_account')
if def_bank:
    values = frappe.db.get_value('Bank Account', def_bank, ['iban', 'bank_account_no'])
    iban_val = None
    bank_no_val = None
    if values:
        if isinstance(values, tuple):
            iban_val, bank_no_val = values[0], values[1]
        else:
            iban_val = values
    if not (iban_val or bank_no_val):
        frappe.throw('Default Bank Account must have either IBAN or Bank Account No.')
    if iban_val:
        if len(iban_val) < MIN_IBAN_LEN or len(iban_val) > MAX_IBAN_LEN:
            frappe.throw('IBAN length must be between {0} and {1} characters.'.format(MIN_IBAN_LEN, MAX_IBAN_LEN))
    if bank_no_val:
        clean_no = bank_no_val.replace(' ', '')
        if len(clean_no) < MIN_BANK_ACCT_NO_LEN or not clean_no.isdigit():
            frappe.throw('Bank Account No must be numeric and at least {0} digits.'.format(MIN_BANK_ACCT_NO_LEN))

if doc.get('custom_document_type') == 'C-Form':
    if not doc.get('custom_c_form_number'):
        frappe.throw('C-Form Number is required for documents marked as C-Form.')
    if not doc.get('custom_document_file'):
        frappe.throw('Please attach the C-Form file in Document File for C-Form submissions.')
    if not doc.get('custom_c_form_received_date'):
        doc.custom_c_form_received_date = frappe.utils.today()
else:
    pass

if doc.get('custom_change_request_type') in ['New Introduction', 'Change Request']:
    docs = doc.get('custom_supplier_documents') or []
    if not docs or len(docs) == 0:
        frappe.throw('At least one Supporting Document must be attached for New Introduction or Change Request.')

TAX_ID_REQUIRED_COUNTRIES = ["India"]
BANK_TRANSFER_OPTIONS = ["Bank Transfer", "NEFT/RTGS"]
MIN_ELIGIBILITY_ROWS = 1
MIN_SUPPORTING_DOC_ROWS = 1

errors = []

today = frappe.utils.getdate(frappe.utils.nowdate())

# Establishment Date cannot be in the future
if doc.get("custom_establishment_date"):
    if frappe.utils.getdate(doc.custom_establishment_date) > today:
        errors.append("Establishment Date cannot be in the future.")

# Tax ID mandatory for specific countries
if doc.get("country") and doc.country in TAX_ID_REQUIRED_COUNTRIES and not doc.get("tax_id"):
    errors.append("Tax ID is mandatory for suppliers in {}.".format(", ".join(TAX_ID_REQUIRED_COUNTRIES)))

# Preferred Payment Method dependent checks
ppm = doc.get("custom_preferred_payment_method")
if ppm:
    if ppm in BANK_TRANSFER_OPTIONS and not doc.get("default_bank_account"):
        errors.append("Default Bank Account is required when Preferred Payment Method is {}.".format(ppm))
    if "UPI" in ppm:
        upi = (doc.get("custom_upi_id") or "").strip()
        if not upi:
            errors.append("UPI ID is required when Preferred Payment Method is UPI.")
        else:
            if "@" not in upi or len(upi) < 5 or len(upi) > 45:
                errors.append("UPI ID appears invalid (expected format like name@bank).")

# Website basic sanity (must start with http/https if provided)
if doc.get("website"):
    w = doc.website.strip()
    if not (w.startswith("http://") or w.startswith("https://")):
        errors.append("Website URL must start with http:// or https://.")

# Contact sanity (very light validation)
if doc.get("email_id"):
    if not frappe.utils.validate_email_address(doc.email_id, False):
        errors.append("Primary Email appears invalid.")

if doc.get("mobile_no"):
    digits = "".join([c for c in doc.mobile_no if c.isdigit()])
    if len(digits) < 7:
        errors.append("Primary Mobile No. appears invalid.")

# Risk review logic
if doc.get("custom_risk_rating"):
    if not doc.get("custom_risk_review_date"):
        errors.append("Risk Review Date is required when Risk Rating is set.")
    else:
        if frappe.utils.getdate(doc.custom_risk_review_date) < today:
            errors.append("Risk Review Date cannot be in the past.")

# Minimum Eligibility Criteria and Supporting Documents
elig = doc.get("custom_eligibility_criteria") or []
docs = doc.get("custom_supporting_documents") or []
if len(elig) < MIN_ELIGIBILITY_ROWS:
    errors.append("At least {} Eligibility Criteria row(s) required.".format(MIN_ELIGIBILITY_ROWS))
if len(docs) < MIN_SUPPORTING_DOC_ROWS:
    errors.append("At least {} Supporting Document(s) required.".format(MIN_SUPPORTING_DOC_ROWS))

# Summarize and finalize
if errors:
    doc.custom_eligibility_complete = 0
    doc.custom_csd_validation_summary = "CSD validation failed:\n- " + "\n- ".join(errors)
    frappe.throw("CSD validation failed. Please review the Validation Summary.")
else:
    doc.custom_eligibility_complete = 1
    doc.custom_csd_validation_summary = "All CSD checks passed on {0}.".format(frappe.utils.formatdate(today))

if not doc.get('valid_from'):
    frappe.throw('Valid From (valid_from) is mandatory.')
if not doc.get('valid_to'):
    frappe.throw('Valid To (valid_to) is mandatory.')
if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('Valid To (valid_to) must be the same or after Valid From (valid_from).')
if not doc.get('scheme_details') or not (doc.scheme_details or '').strip():
    frappe.throw('Scheme Details (scheme_details) is mandatory.')
if doc.get('custom_benefit_value') in (None, ''):
    frappe.throw('Benefit value (custom_benefit_value) is mandatory.')

for row in (doc.items or []):
    if not (row.generic_code or row.item):
        frappe.throw('Each product line must have either a Generic Code or an Item.')

SEEN_GENERIC_CODES = []
for row in (doc.items or []):
    code = row.generic_code
    if code:
        if code in SEEN_GENERIC_CODES:
            frappe.throw("Duplicate generic code '%s' in a single Supplier Product Registration is not allowed." % code)
        SEEN_GENERIC_CODES.append(code)

if doc.get('valid_from') and doc.get('valid_to'):
    if frappe.utils.getdate(doc.valid_to) < frappe.utils.getdate(doc.valid_from):
        frappe.throw('"Valid To" cannot be earlier than "Valid From"')

if doc.custom_suspended==1:
  if not doc.custom_suspension_reason or str(doc.custom_suspension_reason).strip()=="":
    frappe.throw("Suspension Reason is required when Suspended is checked.")
else:
  pass

if doc.get('issue_type')=="Supplier":
  if not doc.get('custom_supplier'):
    frappe.throw("For supplier-related issues, Supplier must be set in the 'Supplier' field.")
else:
  pass

if doc.get('supplier_score'):
  doc.custom_supplier_score_numeric = frappe.utils.flt(doc.get('supplier_score'))
else:
  if not doc.get('custom_supplier_score_numeric'):
    doc.custom_supplier_score_numeric = 0.0

if True:
	# When status is set to 'Paid', ensure payment_reference exists and set paid_on if not present
	if doc.get('status') and str(doc.get('status')).lower() == 'paid':
		if not doc.get('payment_reference'):
			frappe.throw('Payment reference is required when status is Paid.')
		# set paid_on to today if not set
		if not doc.get('paid_on'):
			doc.paid_on = frappe.utils.nowdate()
	else:
		# no automatic clearing of paid_on for non-Paid statuses in this POC
		pass

if True:
	# Require at least one attachment field
	if not doc.get('file') and not doc.get('custom_file'):
		frappe.throw('An attachment is required on Supplier Document (file or custom_file).')
	# Enforce private files by checking the stored path contains "/private/" or 'private' prefix
	file_checked = False
	for f in ['file','custom_file']:
		val = doc.get(f)
		if val:
			if isinstance(val, str) and ('/private/' in val or val.startswith('private')):
				file_checked = True
			else:
				frappe.throw('Attached files must be private. Please upload via Private Files for ' + f + '.')
	if not file_checked:
		frappe.throw('No private attachment detected. Please upload files to private storage.')
	# Populate or normalize a DMS folder-path metadata field for hierarchical grouping in-ERP
	# Use the linked supplier name if available (custom_supplier) else leave generic
	supplier_name = doc.get('custom_supplier') or ''	
	doctype_label = doc.get('document_type') or 'Documents'
	if supplier_name:
		path = '/Suppliers/' + supplier_name + '/' + doctype_label + '/'
		doc.custom_dms_folder_path = path
	else:
		doc.custom_dms_folder_path = '/Suppliers/Unlinked/' + doctype_label + '/'
